/**
 * A question another screen hands Lex to ask: the word page's "Ask Lex
 * about this word", the summary's "Go over my mistakes with Lex".
 *
 * It travels in the navigation state and never in the address, so a link
 * from outside the app can never spend a learner's messages on a question
 * they did not choose. Lex asks it once, in a chat of its own, about the
 * notebook the words are in (which need not be the one on screen).
 */
export interface LexHandoff {
  lexAsk: string;
  /** The notebook the question is about; the one in view when absent. */
  lexNotebookId?: string;
}

/** The state to navigate to /assistant with. */
export function lexHandoff(question: string, notebookId?: string): LexHandoff {
  return notebookId === undefined ? { lexAsk: question } : { lexAsk: question, lexNotebookId: notebookId };
}

/** The handed-over question in a navigation state, if there is a usable one. */
export function handoffOf(state: unknown): { question: string; notebookId?: string } | undefined {
  if (typeof state !== 'object' || state === null || !('lexAsk' in state)) return undefined;
  const ask = state.lexAsk;
  if (typeof ask !== 'string' || ask.trim() === '') return undefined;
  const nb = 'lexNotebookId' in state ? state.lexNotebookId : undefined;
  return typeof nb === 'string' && nb !== '' ? { question: ask, notebookId: nb } : { question: ask };
}
